import { 全屏选择外壳 } from '../组件/全屏选择外壳';
import { 轻提示 } from '../组件/轻提示';
import { 相机图标 } from '../组件/图标';
import { use导航 } from '../路由/导航钩子';
import { 取公司档案 } from '../数据/公司档案';
import type { 团队成员项 } from '../数据/类型';
import {
  按段取分区,
  本公司键,
  合成覆盖,
  作息池,
  规模池,
  融资阶段池,
  行业池,
  相册每组上限,
  福利标签池,
  读资料,
  type 分区定义,
  type 资料形,
} from '../数据/公司主页资料';
import type {
  BFF公开企业,
  BFFTaxonomyItem,
  BFF企业媒体,
  BFF企业媒体用途,
  BFF企业档案,
} from '../数据/BFF契约';
import type { 目录页, Taxonomy查询 } from '../数据/招聘数据源类型';
import { 合并目录页 } from '../数据/目录选择';
import { 从BFF企业档案, 校验企业常用名 } from '../数据/组织映射';
import { BFF错误, 取后端错误文案 } from '../数据/HTTP客户端';
import type { 企业媒体脱离错误 } from '../状态/后端/组织操作';
import { use应用状态 } from '../状态/应用状态';
import 招聘方组织门 from './招聘方组织门';

/** 媒体上传的冻结边界（P1B runtime）：只收 PNG/JPEG，单文件 ≤ 10 MiB */
const 图片字节上限 = 10 * 1024 * 1024;

/** 主营业务上限（P1B runtime）：最多 20 条、每条 200 字 → textarea 总长 20×200+19 个换行 */
const 业务字上限 = 20 * 200 + 19;

/** 团队成员上限（P1B runtime） */
const 成员数上限 = 20;

/** Backend 行业选择只用得到 industries 一个 kind（目录查询 seam 的窄化形态） */
type 行业查询方法 = (kind: 'industries', query: Taxonomy查询) => Promise<目录页<BFFTaxonomyItem>>;
type 企业身份形 = Omit<BFF公开企业, 'profile'> | null;

/** 公司行业选择正文的一行（Task 4）：键是稳定键（HTTP = 目录 ID，Mock = 池内名称）。
 *  行们按「父行后紧跟其可见后代」的树摊平序给出，层级只作缩进。 */
type 公司行业行 = {
  键: string;
  名称: string;
  层级: number;
  可选: boolean;
  有子项: boolean;
  展开: boolean;
  选中: boolean;
};

/** 一个父块（父键 null = 根列表）的分页尾态：错误=文案+重试；还有=加载更多 */
type 公司行业分页 = { 父键: string | null; 还有: boolean; 加载中: boolean; 错误: string | null };

/** A 契约的父页记账（Task 4，两模式的分区根层共用）：打开前先记录触发行与各
 *  .滚动区 祖先的 scrollTop，关闭后由 layout effect 在 wrapper 已恢复显示时
 *  先 focus({ preventScroll: true }) 回仍连接的触发行、再原样还原 scrollTop；
 *  首次挂载不恢复（曾打开 守卫）。 */
function use行业子视图() {
  const [开, 设开] = useState(false);
  const 行引用 = useRef<HTMLButtonElement>(null);
  const 曾打开 = useRef(false);
  const 打开滚动 = useRef<{ 节点: HTMLElement; 顶: number }[]>([]);
  useLayoutEffect(() => {
    if (开) {
      曾打开.current = true;
      return;
    }
    if (!曾打开.current) return;
    曾打开.current = false;
    const 触发行 = 行引用.current;
    if (触发行?.isConnected) 触发行.focus({ preventScroll: true });
    for (const { 节点, 顶 } of 打开滚动.current) 节点.scrollTop = 顶;
    打开滚动.current = [];
  }, [开]);
  const 开层 = () => {
    打开滚动.current = [];
    for (let 节点 = 行引用.current?.parentElement; 节点; 节点 = 节点.parentElement) {
      if (节点.classList.contains('滚动区')) 打开滚动.current.push({ 节点, 顶: 节点.scrollTop });
    }
    设开(true);
  };
  return { 开, 行引用, 开层, 关层: () => 设开(false) };
}

export default function 公司档案分区编辑() {
  const { area: 段 } = useParams<{ area: string }>();
  const { 返回 } = use导航();
  const { 数据源模式 } = use应用状态();
  const 分区 = 按段取分区(段);

  // 地址栏被手改成不存在的分区时不白屏，退回清单
  if (!分区) {
    return (
      // 2026-08-24 全站选择风格统一（C1 定稿）：页底改白
      <次级页外壳 白底>
        <返回栏 返回={返回} />
        <页面大标题 标题="公司主页资料" />
      </次级页外壳>
    );
  }

  return 数据源模式 === 'backend' ? (
    <后端分区入口 分区={分区} 返回={返回} />
  ) : (
    <Mock分区编辑 分区={分区} 返回={返回} />
  );
}

// ── Backend：完整 replacement 草稿 + 权限门 + 两步媒体 ────────────────

/** 深链也必须先过组织门：门后才挂持有草稿的编辑器，
 *  否则直链 /hr/company-profile/basic 会挂出一张空的可编辑表单，
 *  保存下去等于凭空捏造一家企业。空草稿构造函数因此一并删除。
 *  本页是顶层路由、外面没有布局，所以把 返回 交给门：非就绪态也得有返回栏，
 *  否则「重试」那一屏（唯一动作就是重试）会把用户锁死。 */
function 后端分区入口({ 分区, 返回 }: { 分区: 分区定义; 返回: () => void }) {
  return (
    <招聘方组织门 返回={返回}>
      <后端分区编辑 分区={分区} 返回={返回} />
    </招聘方组织门>
  );
}

/** 门后不变量的兑现处：与 公司档案编辑 的 权威企业分区清单 同一口径，
 *  用防御式 return null 而不是 ! 断言 —— 万一有人在门外挂了这个组件，
 *  结果是不渲染，而不是在 从BFF企业档案(undefined) 里崩掉。 */
function 后端分区编辑({ 分区, 返回 }: { 分区: 分区定义; 返回: () => void }) {
  const { 状态 } = use应用状态();
  const 快照 = 状态.企业档案快照;
  if (!快照) return null;
  return <后端分区表单 分区={分区} 返回={返回} 快照={快照} />;
}

function 后端分区表单(
  { 分区, 返回, 快照 }: { 分区: 分区定义; 返回: () => void; 快照: BFF企业档案 },
) {
  const { 状态, 操作, 目录查询 } = use应用状态();
  const 身份 = 状态.当前企业身份;
  // 可编辑写成一个局部布尔表达式，不引入权限框架：
  // admin + 本人关系 verified + 企业 active，三者缺一即只读
  const 当前关系 = 状态.企业关系列表.find((条) => 条.affiliation_id === 状态.当前企业关系编号);
  const 可编辑 = 当前关系?.status === 'verified' &&
    当前关系?.role === 'admin' &&
    当前关系?.organization_status === 'active';

  // 草稿从门后的权威 企业档案快照 构造完整 资料形（进屏即已水合，不存在空草稿态，
  // 也就不再需要「水合晚于进屏」的补初始化分支）
  const [资料, 设资料] = useState<资料形>(() => 从BFF企业档案(快照));
  useEffect(() => {
    // 权威快照前进（409/503 重读、另一端刚发布成功的媒体）：只同步媒体事实，
    // 文本草稿留在用户手里 —— 409 后必须由用户检查再按原保存键重试
    设资料((旧) => ({
      ...旧,
      LOGO媒体: 快照.logo,
      实景媒体: 快照.office_media,
      公司媒体: 快照.company_media,
      实景照片: 快照.office_media.map((媒) => 媒.url),
      公司照片: 快照.company_media.map((媒) => 媒.url),
    }));
  }, [快照]);

  function 改(补丁: Partial<资料形>) {
    设资料((旧) => ({ ...旧, ...补丁 }));
  }

  // ── 媒体：两步协议由 operation 编排；页面只管文件校验、object URL 内存预览、purpose ──
  const 预览集 = useRef<Set<string>>(new Set());
  // 卸载只回收 object URL，绝不把页面卸载当成服务端删除
  useEffect(() => () => {
    预览集.current.forEach((地址) => URL.revokeObjectURL(地址));
  }, []);
  /** 校验 PNG/JPEG 与 10 MiB；通过则生成 object URL 预览并登记待回收 */
  function 校验图片(文件: File): string | null {
    if (文件.type !== 'image/png' && 文件.type !== 'image/jpeg') {
      轻提示('仅支持 PNG / JPEG 图片');
      return null;
    }
    if (文件.size > 图片字节上限) {
      轻提示('图片不超过 10 MiB');
      return null;
    }
    const 地址 = URL.createObjectURL(文件);
    预览集.current.add(地址);
    return 地址;
  }
  function 收预览(地址: string | null) {
    if (!地址) return;
    预览集.current.delete(地址);
    URL.revokeObjectURL(地址);
  }
  const [LOGO预览, 设LOGO预览] = useState<string | null>(null);
  const [组预览表, 设组预览表] = useState<Partial<Record<BFF企业媒体用途, string>>>({});
  // 发布失败（上传已成功、PATCH 未完成）时 operation 抛回的脱离媒体收据：
  // 页面只给用户「放弃（best-effort DELETE）」一个出口，不自动清理
  const [脱离单, 设脱离单] = useState<{ purpose: BFF企业媒体用途; media_id: string } | null>(null);

  async function 发布媒体(purpose: BFF企业媒体用途, 文件: File, 上传中预览: string) {
    try {
      await 操作.上传并发布企业媒体(purpose, 文件);
      // 成功后权威 snapshot 被 operation 用响应替换，预览随之收口
    } catch (错误) {
      const 收据 = (错误 as 企业媒体脱离错误).脱离媒体;
      if (收据) 设脱离单(收据);
      轻提示(取后端错误文案(错误));
    } finally {
      收预览(上传中预览);
      if (purpose === 'organization_logo') 设LOGO预览(null);
      else 设组预览表((旧) => ({ ...旧, [purpose]: undefined }));
    }
  }

  async function 放弃脱离媒体() {
    if (!脱离单) return;
    const 收据 = 脱离单;
    设脱离单(null);
    // best-effort：失败也静默收口（孤儿媒体交由服务端策略），不打扰用户
    await 操作.移除企业媒体(收据.purpose, 收据.media_id).catch(() => {});
  }

  function 选了LOGO(事件: React.ChangeEvent<HTMLInputElement>) {
    const 文件 = 事件.target.files?.[0];
    事件.target.value = ''; // 允许再次选同一张
    if (!文件 || !可编辑) return;
    const 预览 = 校验图片(文件);
    if (!预览) return;
    设LOGO预览(预览);
    void 发布媒体('organization_logo', 文件, 预览);
  }

  async function 移除一张(purpose: 'office_photo' | 'company_photo', 序: number) {
    const 媒体们 = purpose === 'office_photo' ? (资料.实景媒体 ?? []) : (资料.公司媒体 ?? []);
    const 媒体 = 媒体们[序];
    if (!媒体) return;
    // 明确移除：先 PATCH 去引用再 DELETE 已脱离媒体，顺序由 operation 保证
    try {
      await 操作.移除企业媒体(purpose, 媒体.media_id);
    } catch (错误) {
      轻提示(取后端错误文案(错误));
    }
  }

  // ── 保存：完整 replacement（15 字段由 operation 的 转BFF企业档案替换 生成）──
  const 业务行们 = 资料.主营业务.split('\n').map((行) => 行.trim()).filter(Boolean);
  const 缺行业引用 = 资料.行业.trim() !== '' && 资料.行业引用 === undefined;
  // Spec §2：常用名即时输入校验（80 码点/trim/控制字符）；normalized 唯一冲突只由后端裁决
  const [常用名错误, 设常用名错误] = useState<string | null>(null);
  function 改常用名(值: string) {
    设常用名错误(null);
    改({ 企业常用名: 值 });
  }
  async function 保存() {
    if (!可编辑) return;
    if (业务行们.length > 20) {
      轻提示('主营业务最多 20 条');
      return;
    }
    if (业务行们.some((行) => 行.length > 200)) {
      轻提示('每条主营业务不超过 200 字');
      return;
    }
    const 常用名错 = 校验企业常用名(资料.企业常用名 ?? '');
    设常用名错误(常用名错);
    if (常用名错 !== null) return;
    try {
      await 操作.保存企业档案(资料);
      轻提示('已保存');
      返回();
    } catch (错误) {
      // Spec §2：409 organization_name_conflict 是常用名冲突 —— 字段错误 + 保留输入，
      // 不离开页面；409 version_conflict / 503 仍走轻提示（operation 已重读权威 snapshot）
      if (错误 instanceof BFF错误 && 错误.code === 'organization_name_conflict') {
        设常用名错误('这个常用名已被其他企业使用');
        return;
      }
      轻提示(取后端错误文案(错误));
    }
  }

  // ── 行业全屏子视图（Task 4 / R2-2）：查询 state、生命周期与回调自 后端行业区 上移到
  //  本根层，基本信息后代只保留字段行。表/游标与原实现同形；打开时读根项，搜索 250ms
  //  debounce 按 q 查询。review-r1 F1：开着布尔守不了「关闭后又重开」的迟到响应
  //  （重开后开着引用又为真，旧会话响应照样回写），改用页面局部会话代际 —— 开/关层
  //  都递增（尤其关闭），所有数据写入前核对捕获的代际；搜索另记请求序（词变化即递增），
  //  先发后到的旧词响应不覆盖新词结果。 ─────────────────────────────
  const { 开: 行业层开, 行引用: 行业行引用, 开层: 原开行业层, 关层: 原关行业层 } = use行业子视图();
  const [行业搜索词, 设行业搜索词] = useState('');
  const [行业根项, 设行业根项] = useState<BFFTaxonomyItem[]>([]);
  const [行业根游标, 设行业根游标] = useState<string | null>(null);
  // 已展开父项的子项与游标（键 = 父项 id；任意层级、浏览/搜索两模式共用这一个表）
  const [行业子项表, 设行业子项表] = useState<Record<string, BFFTaxonomyItem[]>>({});
  const [行业子游标表, 设行业子游标表] = useState<Record<string, string | null>>({});
  // null = 浏览目录模式；有值 = 显示搜索结果。搜索与浏览共用展开/分页：
  // API 实际返回 nextCursor（搜索尾态单独记账），命中父节点保留 has_children 可展开
  const [行业搜索结果, 设行业搜索结果] = useState<BFFTaxonomyItem[] | null>(null);
  // 搜索专属尾态：加载中/错误/游标独立记账 —— 失败给错误+重试，不伪装成空结果
  const [行业搜索尾态, 设行业搜索尾态] = useState<{
    游标: string | null; 忙: boolean; 错误: string | null;
  }>({ 游标: null, 忙: false, 错误: null });
  // 已请求展开的父项（键 = 父项 id）：展开意图与已到的子项分开记，首载/失败也亮得出分页尾
  const [行业展开表, 设行业展开表] = useState<Record<string, true>>({});
  // 各父块（'' = 根）的请求尾态。分页「加载更多」失败不动（原行为），游标还在可再点
  const [行业取态, 设行业取态] = useState<Record<string, { 忙: boolean; 错误: string | null }>>({});
  const 行业会话代际 = useRef(0);
  const 行业搜索序 = useRef(0);
  const 行业查询方法引用 = useRef<行业查询方法 | null>(目录查询?.查询Taxonomy);
  行业查询方法引用.current = 目录查询?.查询Taxonomy;

  // 开/关层都递增会话代际（F1）：关闭后在飞响应即便在重开之后才返回，也因代际不符被拒；
  // 关闭顺带清搜索 —— 与 选定行业 同一「下一次打开回到浏览模式」口径，也避免半途的
  // 「搜索已开始、结果还是空」的中间态带进新会话
  const 开行业层 = () => {
    行业会话代际.current += 1;
    原开行业层();
  };
  const 关闭行业层 = () => {
    行业会话代际.current += 1;
    // R2-F1：finally 改为按捕获会话收口后，旧会话在飞请求不再自清忙态 —— 关闭时
    // 显式清掉全部取态忙（错误保留给重试入口），否则重开后的 展开/分页 被遗留忙态拦截
    设行业取态((旧) => {
      const 下一: Record<string, { 忙: boolean; 错误: string | null }> = {};
      for (const [键, 态] of Object.entries(旧)) 下一[键] = { ...态, 忙: false };
      return 下一;
    });
    设行业搜索词('');
    设行业搜索结果(null);
    设行业搜索尾态({ 游标: null, 忙: false, 错误: null });
    原关行业层();
  };

  function 设取态(键: string, 补丁: { 忙?: boolean; 错误?: string | null }) {
    // 本次补丁盖已有态（review 终审 Issue 3）：未显式给的键回落已有态，
    // catch 写入的错误不被 finally 的 { 忙: false } 抹掉；首载开始时显式传
    // 错误: null 仍会把上一轮错误清掉，成功回填语义不变。无已有态才落缺省。
    设行业取态((旧) => {
      const 已有 = 旧[键] ?? { 忙: false, 错误: null };
      return { ...旧, [键]: { ...已有, ...补丁 } };
    });
  }

  // 弹开时按需读根项（与 工作经历 已验证的 industries 模式一致）；重试(null) 复用同一读取。
  // 忙 态在 finally 无条件收口（丢弃的响应也不能留下永久「加载中」）；数据写入才受会话代际守卫
  function 读行业根项() {
    const 方法 = 行业查询方法引用.current;
    if (!方法) return;
    const 会话 = 行业会话代际.current;
    void (async () => {
      设取态('', { 忙: true, 错误: null });
      try {
        const 页 = await 方法('industries', { limit: 50 });
        if (行业会话代际.current !== 会话) return;
        设行业根项(页.items);
        设行业根游标(页.nextCursor);
      } catch {
        if (行业会话代际.current !== 会话) {
          return;
        }
        设行业根项([]);
        设行业根游标(null);
        设取态('', { 错误: '加载失败，请重试' });
      } finally {
        // R2-F1：仅本会话收口 —— 旧会话在飞请求的完成不得清掉新会话同键（''）的忙态
        if (行业会话代际.current === 会话) 设取态('', { 忙: false });
      }
    })();
  }
  useEffect(() => {
    if (行业层开) 读行业根项();
    // 打开即读一次；方法经引用取最新，不进依赖
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [行业层开]);

  // 搜索：250ms debounce 后按 q 查询（空串回浏览模式）。F1：词变化即递增搜索请求序，
  // 先发后到的旧词响应不回写；F2：搜索开始即清浏览结果挂专属加载态（浏览结果不残留
  // 冒充搜索结果），失败落错误+重试（不伪装成空结果），成功记 nextCursor 供加载更多
  useEffect(() => {
    const 词 = 行业搜索词.trim();
    const 会话 = 行业会话代际.current;
    const 序 = ++行业搜索序.current;
    if (词 === '') {
      设行业搜索结果(null);
      设行业搜索尾态({ 游标: null, 忙: false, 错误: null });
      return;
    }
    const 方法 = 行业查询方法引用.current;
    if (!方法) return;
    // 搜索开始即离开浏览模式：老浏览行不残留，加载中由搜索尾项呈现
    设行业搜索结果([]);
    设行业搜索尾态({ 游标: null, 忙: true, 错误: null });
    const 计时器 = setTimeout(() => {
      void (async () => {
        try {
          const 页 = await 方法('industries', { q: 词, limit: 50 });
          if (行业会话代际.current !== 会话 || 行业搜索序.current !== 序) return;
          设行业搜索结果(页.items);
          设行业搜索尾态({ 游标: 页.nextCursor, 忙: false, 错误: null });
        } catch {
          if (行业会话代际.current !== 会话 || 行业搜索序.current !== 序) return;
          设行业搜索结果([]);
          设行业搜索尾态({ 游标: null, 忙: false, 错误: '加载失败，请重试' });
        }
      })();
    }, 250);
    return () => clearTimeout(计时器);
  }, [行业搜索词]);

  // 搜索分页（F2）：沿搜索尾态的游标请求下一页，合并进搜索结果；失败不动（可再点）。
  // 守卫同首查：会话代际 + 搜索请求序
  async function 搜索加载更多() {
    const 游标 = 行业搜索尾态.游标;
    if (游标 === null || 行业搜索尾态.忙) return;
    const 方法 = 行业查询方法引用.current;
    if (!方法) return;
    const 会话 = 行业会话代际.current;
    const 序 = 行业搜索序.current;
    设行业搜索尾态((旧) => ({ ...旧, 忙: true, 错误: null }));
    try {
      const 页 = await 方法('industries', { q: 行业搜索词.trim(), cursor: 游标, limit: 50 });
      if (行业会话代际.current !== 会话 || 行业搜索序.current !== 序) return;
      设行业搜索结果((旧) => 合并目录页(旧 ?? [], 页.items));
      设行业搜索尾态({ 游标: 页.nextCursor, 忙: false, 错误: null });
    } catch {
      // R2-F2：追加失败保留累计行与原游标，错误可重试（沿原游标续传），不伪装「没有更多」
      if (行业会话代际.current === 会话 && 行业搜索序.current === 序) {
        设行业搜索尾态((旧) => ({ ...旧, 忙: false, 错误: '加载失败，请重试' }));
      }
    } finally {
      // R2-F1：仅本会话本请求序收口，不带走别的会话/请求的忙态
      if (行业会话代际.current === 会话 && 行业搜索序.current === 序) {
        设行业搜索尾态((旧) => ({ ...旧, 忙: false }));
      }
    }
  }

  // 搜索失败重试（F2 / R2-F2）：首查失败沿词重发首屏；追加失败沿原词原游标续传
  //（累计行保留，不重开首屏），恢复后错误消失
  async function 搜索重试() {
    const 词 = 行业搜索词.trim();
    const 方法 = 行业查询方法引用.current;
    if (词 === '' || !方法) return;
    const 会话 = 行业会话代际.current;
    const 序 = ++行业搜索序.current;
    const 游标 = 行业搜索尾态.游标;
    if (游标 !== null) {
      设行业搜索尾态((旧) => ({ ...旧, 忙: true, 错误: null }));
      try {
        const 页 = await 方法('industries', { q: 词, cursor: 游标, limit: 50 });
        if (行业会话代际.current !== 会话 || 行业搜索序.current !== 序) return;
        设行业搜索结果((旧) => 合并目录页(旧 ?? [], 页.items));
        设行业搜索尾态({ 游标: 页.nextCursor, 忙: false, 错误: null });
      } catch {
        if (行业会话代际.current === 会话 && 行业搜索序.current === 序) {
          设行业搜索尾态((旧) => ({ ...旧, 忙: false, 错误: '加载失败，请重试' }));
        }
      }
      return;
    }
    设行业搜索结果([]);
    设行业搜索尾态({ 游标: null, 忙: true, 错误: null });
    try {
      const 页 = await 方法('industries', { q: 词, limit: 50 });
      if (行业会话代际.current !== 会话 || 行业搜索序.current !== 序) return;
      设行业搜索结果(页.items);
      设行业搜索尾态({ 游标: 页.nextCursor, 忙: false, 错误: null });
    } catch {
      if (行业会话代际.current !== 会话 || 行业搜索序.current !== 序) return;
      设行业搜索尾态((旧) => ({ ...旧, 忙: false, 错误: '加载失败，请重试' }));
    }
  }

  async function 读行业子项(父键: string) {
    const 方法 = 行业查询方法引用.current;
    if (!方法) return;
    const 会话 = 行业会话代际.current;
    设行业展开表((旧) => ({ ...旧, [父键]: true }));
    设取态(父键, { 忙: true, 错误: null });
    try {
      const 页 = await 方法('industries', { parentId: 父键, limit: 50 });
      if (行业会话代际.current !== 会话) return;
      设行业子项表((旧) => ({ ...旧, [父键]: 页.items }));
      设行业子游标表((旧) => ({ ...旧, [父键]: 页.nextCursor }));
    } catch {
      if (行业会话代际.current === 会话) 设取态(父键, { 错误: '加载失败，请重试' });
    } finally {
      // R2-F1：仅本会话收口 —— 旧会话在飞请求的完成不得清掉新会话同键的忙态
      if (行业会话代际.current === 会话) 设取态(父键, { 忙: false });
    }
  }

  function 展开行业(父键: string) {
    // 已加载不再请求（原行为）；在飞不重复排队；失败后经 重试(父键) 再来
    if (行业子项表[父键] !== undefined || 行业取态[父键]?.忙) return;
    void 读行业子项(父键);
  }

  async function 加载更多行业(父键: string | null) {
    // F2：搜索态的根尾（父键 null）接搜索分页，浏览态接目录根分页
    if (父键 === null && 行业搜索结果 !== null) return 搜索加载更多();
    const 游标 = 父键 === null ? 行业根游标 : 行业子游标表[父键];
    if (游标 === null || 游标 === undefined) return;
    const 方法 = 行业查询方法引用.current;
    if (!方法) return;
    const 会话 = 行业会话代际.current;
    设取态(父键 ?? '', { 忙: true });
    try {
      const 页 = await 方法('industries', { parentId: 父键 ?? undefined, cursor: 游标, limit: 50 });
      if (行业会话代际.current !== 会话) return;
      if (父键 === null) {
        设行业根项((旧) => 合并目录页(旧, 页.items));
        设行业根游标(页.nextCursor);
      } else {
        设行业子项表((旧) => ({ ...旧, [父键]: 合并目录页(旧[父键] ?? [], 页.items) }));
        设行业子游标表((旧) => ({ ...旧, [父键]: 页.nextCursor }));
      }
    } catch {
      // 失败不动，用户可再点（原行为）
    } finally {
      // R2-F1：仅本会话收口，不带走新会话同键（''/父键）的忙态
      if (行业会话代际.current === 会话) 设取态(父键 ?? '', { 忙: false });
    }
  }

  function 重试行业(父键: string | null) {
    if (父键 === null) {
      // F2：搜索态根尾错误的重试接搜索首查；浏览态接根项重读
      if (行业搜索结果 !== null) void 搜索重试();
      else 读行业根项();
      return;
    }
    void 读行业子项(父键);
  }

  function 选定行业(键: string) {
    // 名称与引用从同一条 DTO 原子落草稿（键 = 目录 ID，同名不同 ID 不串），绝不按名反查；
    // 只有 selectable 叶子可选。选中即收口子视图并清搜索，下一次打开回到浏览模式
    const 项 = 行业搜索结果?.find((候选) => 候选.id === 键)
      ?? 行业根项.find((候选) => 候选.id === 键)
      ?? Object.values(行业子项表).flat().find((候选) => 候选.id === 键);
    if (!项 || !项.selectable) return;
    改({ 行业: 项.display_name, 行业引用: { id: 项.id, display_name: 项.display_name } });
    设行业搜索词('');
    设行业搜索结果(null);
    关闭行业层();
  }

  // DTO → 展示行（Backend 映射只在根层做一次；选中回显按稳定键，不吃显示名）。
  // F3：搜索命中父节点保留真实 has_children —— 搜索行与浏览模式共用
  // 读行业子项/行业展开表/行业子项表，命中父节点可展开（选定行业 的子项表查找不受影响）
  const 行业转行 = (项: BFFTaxonomyItem, 层级: number): 公司行业行 => ({
    键: 项.id,
    名称: 项.display_name,
    层级,
    可选: 项.selectable,
    有子项: 项.has_children,
    展开: 行业展开表[项.id] === true,
    选中: 资料.行业引用?.id === 项.id,
  });
  const 行业行们: 公司行业行[] = [];
  const 摊平 = (项们: BFFTaxonomyItem[], 层级: number) => {
    for (const 项 of 项们) {
      行业行们.push(行业转行(项, 层级));
      const 子们 = 行业子项表[项.id];
      if (子们 !== undefined) 摊平(子们, 层级 + 1);
    }
  };
  // 搜索态摊平搜索结果（已展开的命中父项跟着已加载子项），浏览态摊平目录根
  摊平(行业搜索结果 ?? 行业根项, 0);
  // 分页尾（F2）：搜索态的根尾（父键 null）用搜索专属尾态并接搜索查询，浏览态用根项
  // 尾态；子块尾态两种模式共用同一表（展开表/子游标表/取态）
  const 子块分页们: 公司行业分页[] = Object.keys(行业展开表).map((父键) => ({
    父键,
    还有: (行业子游标表[父键] ?? null) !== null,
    加载中: 行业取态[父键]?.忙 === true,
    错误: 行业取态[父键]?.错误 ?? null,
  }));
  const 行业分页们: 公司行业分页[] = 行业搜索结果 !== null
    ? [
        {
          父键: null,
          还有: 行业搜索尾态.游标 !== null,
          加载中: 行业搜索尾态.忙,
          错误: 行业搜索尾态.错误,
        },
        ...子块分页们,
      ]
    : [
        {
          父键: null,
          还有: 行业根游标 !== null,
          加载中: 行业取态['']?.忙 === true,
          错误: 行业取态['']?.错误 ?? null,
        },
        ...子块分页们,
      ];

  // R2-F2：搜索已结算（非忙、无错误）且零行 → 明确空态文案，不静默空白（§5.4 空结果表达）
  const 搜索空态文案 = 行业搜索结果 !== null &&
    行业搜索尾态.忙 === false && 行业搜索尾态.错误 === null && 行业搜索结果.length === 0
    ? '没有匹配的行业'
    : undefined;

  return (
    // 2026-08-24 全站选择风格统一（C1 定稿）：页底改白
    <次级页外壳 白底>
      {/* Task 4：行业全屏子视图打开时，含返回/保存栏的整个父表单 wrapper 保持挂载但
          hidden —— 仓库没有全局 [hidden] 规则，内联 display 会压过 UA 折叠，必须随
          子视图开合显式切换；wrapper 接管外壳的满高语义（flex:1/min-height:0/纵向
          flex），选择正文是下面的内容兄弟，绝不能藏进自己的 hidden 祖先。 */}
      <div
        hidden={行业层开}
        style={{ flex: 1, minHeight: 0, display: 行业层开 ? 'none' : 'flex', flexDirection: 'column' }}
      >
      <返回栏
        返回={返回}
        右侧={
          可编辑 ? (
            <button
              className={`${样式.保存键} 可点`}
              disabled={缺行业引用}
              onClick={保存}
            >
              保存
            </button>
          ) : null
        }
      />

      <页面大标题 标题={分区.键} />

      {!可编辑 ? (
        <滚动区 样式覆盖={{ padding: '0 18px' }}>
          <div className={样式.字段标签} style={{ color: 'var(--次要浅)' }}>
            仅企业管理员可修改
          </div>
        </滚动区>
      ) : null}

      {可编辑 && 脱离单 ? (
        <滚动区 样式覆盖={{ padding: '0 18px 8px' }}>
          <button className={`${样式.加一条} 可点`} onClick={() => void 放弃脱离媒体()}>
            放弃未发布的照片
          </button>
        </滚动区>
      ) : null}

      {/* 长文分区：整屏 textarea（字数在右下角）；其余分区：可滚的字段区 */}
      {分区.键 === '公司介绍' ? (
        <整屏文本
          值={资料.公司介绍}
          上限={500}
          标题="公司介绍"
          禁用={!可编辑}
          改变={(值) => 改({ 公司介绍: 值 })}
        />
      ) : null}

      {分区.键 === '主营业务' ? (
        // Backend 主营业务即 business_items：一行一条，最多 20 条、每条 200 字
        //（保存时校验条数与单条长度；textarea 总长只是这三者的物理并集）
        <整屏文本
          值={资料.主营业务}
          上限={业务字上限}
          标题="主营业务"
          禁用={!可编辑}
          改变={(值) => 改({ 主营业务: 值 })}
        />
      ) : null}

      {分区.键 === '产品介绍' ? (
        <整屏文本
          值={资料.产品介绍}
          上限={300}
          标题="产品介绍"
          禁用={!可编辑}
          改变={(值) => 改({ 产品介绍: 值 })}
        />
      ) : null}

      {分区.键 === '基本信息' ? (
        <后端基本信息区
          资料={资料}
          改={改}
          可编辑={可编辑}
          身份={身份}
          常用名错误={常用名错误}
          改常用名={改常用名}
          LOGO预览={LOGO预览}
          选了LOGO={选了LOGO}
          开行业层={开行业层}
          行业行引用={行业行引用}
        />
      ) : null}

      {分区.键 === '公司福利' ? <公司福利区 资料={资料} 改={改} 禁用={!可编辑} /> : null}

      {分区.键 === '公司相册' ? (
        <字段区>
          <后端媒体组
            标签="实景照片"
            媒体们={资料.实景媒体 ?? []}
            预览={组预览表.office_photo}
            可编辑={可编辑}
            选了图={(文件) => {
              const 预览 = 校验图片(文件);
              if (!预览) return;
              设组预览表((旧) => ({ ...旧, office_photo: 预览 }));
              void 发布媒体('office_photo', 文件, 预览);
            }}
            移除一张={(序) => void 移除一张('office_photo', 序)}
          />
          <后端媒体组
            标签="公司照片"
            媒体们={资料.公司媒体 ?? []}
            预览={组预览表.company_photo}
            可编辑={可编辑}
            选了图={(文件) => {
              const 预览 = 校验图片(文件);
              if (!预览) return;
              设组预览表((旧) => ({ ...旧, company_photo: 预览 }));
              void 发布媒体('company_photo', 文件, 预览);
            }}
            移除一张={(序) => void 移除一张('company_photo', 序)}
            末条
          />
        </字段区>
      ) : null}

      {分区.键 === '团队介绍' ? (
        <团队介绍区 资料={资料} 改={改} 禁用={!可编辑} 人数上限={成员数上限} />
      ) : null}
      </div>

      {/* Task 4：行业全屏子视图（两模式共用 公司行业选择正文，R2-2 裁定的根层直连兄弟子页）。
          开着才挂载；选定/关闭回调写回本根层草稿，外壳按 A 契约管焦点/Escape。 */}
      {行业层开 ? (
        <公司行业选择正文
          搜索词={行业搜索词}
          改搜索词={设行业搜索词}
          行们={行业行们}
          分页们={行业分页们}
          空态文案={搜索空态文案}
          加载更多={加载更多行业}
          重试={重试行业}
          关闭={关闭行业层}
          选定={选定行业}
          展开={展开行业}
        />
      ) : null}
    </次级页外壳>
  );
}

/** Backend 基本信息：企业常用名 · 品牌名称 · 公司 LOGO · 行业（taxonomy）· 规模 · 融资阶段 · 办公地址，
 *  外加只读的「工商全称（已核验）」—— 第三方核验事实，企业侧不可编辑。
 *  Spec §2 三名独立：常用名（display_name，目录/公开企业同源）与品牌名（brand_name）
 *  各是各的输入槽，工商全称只读、为空诚实显示未提供，不回填常用名。
 *  Task 4（R2-2）：行业查询状态上移分区根层，这里只收字段行需要的打开回调与触发行引用。 */
